    public static GemInstance socketed(LootCategory category, ItemStack gemStack, int slot) {
        DynamicHolder<Gem> gem = GemItem.getGem(gemStack);
        Purity purity = GemItem.getPurity(gemStack);

        if (gem.isBound()) {
